+
+typedef struct {
+    char c;
+    int bold;
+    int shadow;
+} Cell;
+
+typedef struct {
+    Cell cells[MAX_COLS][MAX_ROWS];
+    int cols;
+    int rows;
+    int async;
+    int bold;
+    int all_bold;
+    int no_bold;
